//! Every command through the real binary, end to end (M3 step 9): keys, init, pack, `feed add`
//! and `refresh`, `verify` and `inspect`, on the layout of an ordinary non-Rust app. Keys are
//! generated by the binary at test time, and every command's output is scanned for every secret
//! generated so far.
//!
//! The feeds and key sets the binary wrote are also read back in-test with the core verifiers
//! (never trusting the binary's own `verify` alone).

mod common;

use std::cell::RefCell;
use std::fs;
use std::path::{Path, PathBuf};
use std::process::Output;

use base64::Engine;
use base64::engine::general_purpose::STANDARD;
use common::*;
use ed25519_dalek::SigningKey;
use ed25519_dalek::pkcs8::DecodePrivateKey;
use lunepack_core::{
    AppId, ArtifactRef, Channel, Clock, ClockReading, Hasher, ManifestDocument, PayloadKind,
    ReleaseDoc, RollbackFloor, Sha256Digest, Signer, TrustedRoot, U53, VerifiedFeed,
    VerifiedKeySet, next_feed, sign_envelope, verify_feed, verify_key_set,
};
use lunepack_crypto::{Ed25519Signer, Ed25519Verifier, Sha256Hasher};
use lunepack_testkit::exe_headers;

const APP: &str = "org.example.hello";
const T0: u64 = 1_800_000_000;
const DAY: u64 = 86_400;
const WIN: &str = "windows-x86_64";

struct At(u64);

impl Clock for At {
    fn now_unix_secs(&self) -> u64 {
        self.0
    }
}

struct Key {
    path: PathBuf,
    public: String,
}

fn s(path: &Path) -> &str {
    path.to_str().expect("utf-8 path")
}

fn hex(text: &str) -> [u8; 32] {
    let bytes: Vec<u8> = (0..32)
        .map(|i| u8::from_str_radix(&text[2 * i..2 * i + 2], 16).unwrap())
        .collect();
    bytes.try_into().unwrap()
}

fn spec(k: &Key) -> String {
    format!("file:{}", s(&k.path))
}

/// A second and third target that every host can pack: Unix hosts take the Linux ones, a Windows
/// host cannot pack them (M3-D10).
fn other_targets() -> Vec<&'static str> {
    if cfg!(windows) {
        vec!["windows-aarch64"]
    } else {
        vec!["linux-x86_64", "linux-aarch64"]
    }
}

struct World {
    dir: tempfile::TempDir,
    config: PathBuf,
    root: Key,
    release: Vec<Key>,
    secrets: RefCell<Vec<Vec<u8>>>,
}

impl World {
    fn new(release_keys: usize) -> World {
        let dir = tempfile::tempdir().unwrap();
        let mut w = World {
            config: dir.path().join("lunepack.toml"),
            root: Key {
                path: PathBuf::new(),
                public: String::new(),
            },
            release: Vec::new(),
            secrets: RefCell::new(Vec::new()),
            dir,
        };
        w.root = w.new_key("root");
        w.release = (0..release_keys)
            .map(|i| w.new_key(&format!("release{i}")))
            .collect();
        let out = w.run(
            &["init", "--app-id", APP, "--root-key", &w.root.public],
            &[],
        );
        assert_ok(&out, "init");
        w
    }

    fn cmd(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let output = run(args, env);
        let secrets = self.secrets.borrow();
        let refs: Vec<&[u8]> = secrets.iter().map(Vec::as_slice).collect();
        assert_no_secrets(&output, &refs);
        output
    }

    fn run(&self, args: &[&str], env: &[(&str, &str)]) -> Output {
        let mut full = vec!["--config", s(&self.config)];
        full.extend_from_slice(args);
        self.cmd(&full, env)
    }

    /// Like [`World::run`] with `SOURCE_DATE_EPOCH` set to `epoch`.
    fn run_at(&self, epoch: u64, args: &[&str]) -> Output {
        self.run(args, &[("SOURCE_DATE_EPOCH", &epoch.to_string())])
    }

    fn new_key(&self, name: &str) -> Key {
        let base = self.dir.path().join(name);
        let out = self.cmd(&["keys", "gen", s(&base)], &[]);
        assert_ok(&out, "keys gen");
        let path = base.with_extension("key");
        let pem = fs::read_to_string(&path).unwrap();
        let seed = SigningKey::from_pkcs8_pem(&pem).unwrap().to_bytes();
        let mut secrets = self.secrets.borrow_mut();
        secrets.push(pem.into_bytes());
        secrets.push(seed.to_vec());
        Key {
            path,
            public: field(&stdout(&out), "public:"),
        }
    }

    /// A release dir with `keys.json` (the listed release keys, threshold 1) written at `T0`.
    fn release_dir(&self, name: &str, keys: &[&Key]) -> PathBuf {
        let dir = self.dir.path().join(name);
        fs::create_dir(&dir).unwrap();
        self.keys_set(&dir, keys);
        dir
    }

    fn keys_set(&self, dir: &Path, keys: &[&Key]) {
        assert_ok(&self.keys_set_with(dir, keys, T0, &[]), "keys set");
    }

    /// `keys set` at `epoch` with `extra` flags; the output is the caller's to judge.
    fn keys_set_with(&self, dir: &Path, keys: &[&Key], epoch: u64, extra: &[&str]) -> Output {
        let mut args = vec!["keys", "set", "--release-dir", s(dir)];
        for k in keys {
            args.extend_from_slice(&["--release-key", &k.public]);
        }
        let root = spec(&self.root);
        args.extend_from_slice(&["--sign", &root]);
        args.extend_from_slice(extra);
        self.run_at(epoch, &args)
    }

    fn pack(&self, input: &Path, dir: &Path, version: &str, target: &str, key: &Key) -> Output {
        self.pack_signed(input, dir, version, target, &[key])
    }

    fn pack_signed(
        &self,
        input: &Path,
        dir: &Path,
        version: &str,
        target: &str,
        keys: &[&Key],
    ) -> Output {
        self.pack_signed_at(T0, input, dir, version, target, keys)
    }

    fn pack_signed_at(
        &self,
        epoch: u64,
        input: &Path,
        dir: &Path,
        version: &str,
        target: &str,
        keys: &[&Key],
    ) -> Output {
        let signers: Vec<String> = keys.iter().map(|k| spec(k)).collect();
        let mut args = vec![
            "pack",
            "--input",
            s(input),
            "--version",
            version,
            "--target",
            target,
            "--release-dir",
            s(dir),
        ];
        for signer in &signers {
            args.extend_from_slice(&["--sign", signer]);
        }
        self.run_at(epoch, &args)
    }

    fn feed(
        &self,
        verb: &str,
        dir: &Path,
        version: Option<&str>,
        key: &Key,
        epoch: u64,
        extra: &[&str],
    ) -> Output {
        let signer = spec(key);
        let mut args = vec![
            "feed",
            verb,
            "--release-dir",
            s(dir),
            "--channel",
            "stable",
            "--sign",
            &signer,
        ];
        if let Some(v) = version {
            args.extend_from_slice(&["--version", v]);
        }
        args.extend_from_slice(extra);
        self.run_at(epoch, &args)
    }

    fn verify(&self, dir: &Path, at: Option<u64>) -> Output {
        let at = at.map(|t| t.to_string());
        let mut args = vec!["verify", s(dir)];
        if let Some(t) = &at {
            args.extend_from_slice(&["--at", t]);
        }
        self.run(&args, &[])
    }

    fn keys(&self, dir: &Path) -> VerifiedKeySet {
        let root = TrustedRoot::from_parts(
            AppId::parse(APP).unwrap(),
            1,
            1,
            &[hex(&self.root.public)],
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .unwrap();
        verify_key_set(
            &root,
            &fs::read(dir.join("keys.json")).unwrap(),
            &RollbackFloor::default(),
            &ClockReading::read(&At(T0), None),
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .expect("keys.json verifies")
    }

    /// The feed the binary wrote, read back with the core verifier, time checks skipped.
    fn read_feed(&self, dir: &Path) -> VerifiedFeed {
        verify_feed(
            &self.keys(dir),
            &fs::read(dir.join("feed-stable.json")).unwrap(),
            &AppId::parse(APP).unwrap(),
            &Channel::parse("stable").unwrap(),
            &RollbackFloor::default(),
            &ClockReading::read(&At(T0), Some(u64::MAX)),
            &Ed25519Verifier,
        )
        .expect("the feed verifies")
    }
}

/// Deterministic noise (xorshift64), incompressible.
fn noise(seed: u64, len: usize) -> Vec<u8> {
    let mut x = seed | 1;
    (0..len)
        .map(|_| {
            x ^= x << 13;
            x ^= x >> 7;
            x ^= x << 17;
            (x >> 24) as u8
        })
        .collect()
}

fn text(len: usize) -> Vec<u8> {
    b"The quick brown fox jumps over the lazy dog; pack me small.\n"
        .iter()
        .copied()
        .cycle()
        .take(len)
        .collect()
}

fn write(root: &Path, rel: &str, bytes: &[u8]) {
    let path = root.join(rel);
    fs::create_dir_all(path.parent().unwrap()).unwrap();
    fs::write(path, bytes).unwrap();
}

/// An ordinary non-Rust app's build output (M3-D13): no symlink, no Cargo file.
fn app_tree() -> tempfile::TempDir {
    let input = tempfile::tempdir().unwrap();
    let root = input.path();
    write(root, "MyApp.exe", &exe_headers::pe(0x8664, 48 * 1024));
    write(
        root,
        "lib/libfoo.so",
        &exe_headers::elf(183, false, 32 * 1024),
    );
    write(root, "bin/helper.dll", &exe_headers::pe(0xAA64, 32 * 1024));
    let mut png = vec![0x89, 0x50, 0x4E, 0x47, 0x0D, 0x0A, 0x1A, 0x0A];
    png.extend(noise(7, 4_000));
    write(root, "assets/logo.png", &png);
    write(
        root,
        "assets/data.json",
        &br#"{"name": "MyApp", "items": [1, 2, 3]}"#.repeat(40),
    );
    write(root, "assets/fonts/ui/Regular.txt", &text(3_000));
    write(root, "README.txt", &text(2_000));
    input
}

fn copy_dir(from: &Path, to: &Path) {
    fs::create_dir_all(to).unwrap();
    for e in fs::read_dir(from).unwrap() {
        let e = e.unwrap();
        let dest = to.join(e.file_name());
        if e.file_type().unwrap().is_dir() {
            copy_dir(&e.path(), &dest);
        } else {
            fs::copy(e.path(), dest).unwrap();
        }
    }
}

/// Flips one bit in the middle of the file.
fn flip(path: &Path) {
    let mut bytes = fs::read(path).unwrap();
    let at = bytes.len() / 2;
    bytes[at] ^= 1;
    fs::write(path, bytes).unwrap();
}

/// A packed release `version` of `targets` and a `stable` feed listing them, all signed by the
/// first release key.
struct Released {
    w: World,
    input: tempfile::TempDir,
    dir: PathBuf,
}

fn released(version: &str, targets: &[&str]) -> Released {
    let w = World::new(1);
    let input = app_tree();
    let dir = w.release_dir("rel", &[&w.release[0]]);
    for t in targets {
        assert_ok(&w.pack(input.path(), &dir, version, t, &w.release[0]), t);
    }
    assert_ok(
        &w.feed("add", &dir, Some(version), &w.release[0], T0, &[]),
        "feed add",
    );
    Released { w, input, dir }
}

/// Test 1: the full flow.
#[test]
fn full_flow() {
    let other = other_targets()[0];
    let r = released("4.0.0", &[WIN, other]);
    let w = &r.w;
    let out = w.verify(&r.dir, Some(T0));
    assert_ok(&out, "verify");
    let log = stdout(&out);
    for t in [WIN, other] {
        assert!(
            log.contains(&format!("4.0.0/{t}.manifest.json: manifest and pack ok")),
            "{log}"
        );
    }
    assert!(log.contains("feed-stable.json"), "{log}");

    let out = w.run(
        &["inspect", s(&r.dir), "--at", &T0.to_string(), "--entries"],
        &[],
    );
    assert_ok(&out, "inspect");
    let shown = stdout(&out);
    for t in [WIN, other] {
        assert!(shown.contains(&format!("    {t}:")), "{shown}");
    }
    assert!(shown.contains("release 4.0.0: rollout everyone, 2 target(s)"));
    assert!(
        shown.contains("feed stable (feed-stable.json): seq"),
        "{shown}"
    );
    assert!(shown.contains("threshold 1"), "{shown}");
    let codec_of = |path: &str| -> String {
        let line = shown
            .lines()
            .find(|l| l.trim_start().starts_with(&format!("{path}  file")))
            .unwrap_or_else(|| panic!("no entry line for {path}: {shown}"));
        line.split("codec ")
            .nth(1)
            .and_then(|r| r.split_whitespace().next())
            .unwrap()
            .to_owned()
    };
    assert!(["bcj-x86+lzma2", "bcj2"].contains(&codec_of("MyApp.exe").as_str()));
    assert_eq!(codec_of("lib/libfoo.so"), "bcj-arm64+lzma2");
    assert_eq!(codec_of("bin/helper.dll"), "bcj-arm64+lzma2");
    assert_eq!(codec_of("assets/logo.png"), "stored");
    assert_eq!(codec_of("README.txt"), "lzma2");
    assert!(shown.contains("assets/fonts/ui  dir"), "{shown}");

    // The filters pick what they name, and an unknown target is a usage-level failure.
    let out = w.run(
        &[
            "inspect",
            s(&r.dir),
            "--at",
            &T0.to_string(),
            "--target",
            WIN,
        ],
        &[],
    );
    assert_ok(&out, "inspect --target");
    assert!(!stdout(&out).contains(&format!("    {other}:")));
    let out = w.run(&["inspect", s(&r.dir), "--target", "plan9-mips"], &[]);
    assert_fails(&out, 1, "inspect with an unknown target");
    drop(r.input);
}

/// Test 2: one tampered byte or a missing file, each on its own copy of the release dir.
#[test]
fn tampering_fails_verify() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    assert_ok(&w.verify(&r.dir, Some(T0)), "untouched copy source");

    let cases: [(&str, &str); 6] = [
        ("pack frame byte", "4.0.0/windows-x86_64.pack"),
        (
            "manifest payload byte",
            "4.0.0/windows-x86_64.manifest.json",
        ),
        ("feed byte", "feed-stable.json"),
        ("keys.json byte", "keys.json"),
        ("deleted pack", "4.0.0/windows-x86_64.pack"),
        ("deleted manifest", "4.0.0/windows-x86_64.manifest.json"),
    ];
    for (i, (what, file)) in cases.iter().enumerate() {
        let copy = w.dir.path().join(format!("tampered-{i}"));
        copy_dir(&r.dir, &copy);
        let path = copy.join(file);
        if what.starts_with("deleted") {
            fs::remove_file(&path).unwrap();
        } else {
            flip(&path);
        }
        let out = w.verify(&copy, Some(T0));
        let err = assert_fails(&out, 1, what);
        assert!(err.starts_with("error: "), "{what}: {err:?}");
        if what.starts_with("deleted") {
            assert!(err.contains("does not exist"), "{what}: {err:?}");
        }
        // inspect refuses to show anything from the same copy.
        let out = w.run(&["inspect", s(&copy), "--at", &T0.to_string()], &[]);
        assert_fails(&out, 1, what);
        assert!(
            stdout(&out).is_empty(),
            "{what}: inspect printed {:?}",
            stdout(&out)
        );
    }
    assert_ok(&w.verify(&r.dir, Some(T0)), "the original is untouched");
}

/// F1: entries that share one frame's bytes are each checked under their own size, SHA-256 and
/// descriptor. The packer never writes two entries with one frame and different hashes, so the
/// manifest is re-signed in-test with the release key, and the feed is signed in-test so `verify`
/// and `inspect` reach it; `feed add` refuses it through its own check. The unchanged re-signed
/// manifest passes every path, so the failure comes from the second entry alone.
#[test]
fn shared_frame_entries_are_each_checked() {
    let w = World::new(1);
    let input = tempfile::tempdir().unwrap();
    write(input.path(), "a.txt", &text(3_000));
    write(input.path(), "b.txt", &text(3_000));
    let dir = w.release_dir("rel", &[&w.release[0]]);
    assert_ok(
        &w.pack(input.path(), &dir, "4.0.0", WIN, &w.release[0]),
        "pack",
    );
    let signer = Ed25519Signer::from_key_file(&w.release[0].path).unwrap();
    let signers: [&dyn Signer; 1] = [&signer];
    let manifest_rel = format!("4.0.0/{WIN}.manifest.json");

    for tamper in [false, true] {
        let what = if tamper {
            "second entry's sha256"
        } else {
            "unchanged"
        };
        let copy = w.dir.path().join(format!("shared-{tamper}"));
        copy_dir(&dir, &copy);
        let path = copy.join(&manifest_rel);
        let envelope: serde_json::Value =
            serde_json::from_slice(&fs::read(&path).unwrap()).unwrap();
        let payload = STANDARD
            .decode(envelope["payload"].as_str().unwrap())
            .unwrap();
        let mut doc: ManifestDocument = serde_json::from_slice(&payload).unwrap();
        let files: Vec<usize> = (0..doc.entries.len())
            .filter(|&i| doc.entries[i].kind == "file")
            .collect();
        assert_eq!(files.len(), 2, "{what}");
        let (a, b) = (&doc.entries[files[0]], &doc.entries[files[1]]);
        assert!(
            a.frame.is_some() && a.frame == b.frame,
            "{what}: one shared frame"
        );
        if tamper {
            doc.entries[files[1]].sha256 = Some(Sha256Digest::from_bytes([0x5a; 32]));
        }
        let manifest = sign_envelope(
            PayloadKind::Manifest,
            &doc.to_payload(),
            &signers,
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .unwrap();
        fs::write(&path, &manifest).unwrap();

        // The feed writers' check (I1) runs before anything is placed.
        let out = w.feed("add", &copy, Some("4.0.0"), &w.release[0], T0, &[]);
        if tamper {
            let err = assert_fails(&out, 1, "feed add");
            assert!(err.contains("b.txt does not decode"), "{err:?}");
            assert!(!copy.join("feed-stable.json").exists());
        } else {
            assert_ok(&out, "feed add");
        }

        // A feed listing the manifest, signed in-test, for `verify` and `inspect`.
        let mut targets = std::collections::BTreeMap::new();
        targets.insert(
            WIN.to_owned(),
            ArtifactRef {
                path: manifest_rel.clone(),
                size: U53::new(manifest.len() as u64).unwrap(),
                sha256: Sha256Hasher.sha256(&manifest),
            },
        );
        let release = ReleaseDoc {
            version: "4.0.0".to_owned(),
            targets,
            rollout: None,
        };
        let feed = next_feed(
            None,
            &AppId::parse(APP).unwrap(),
            &Channel::parse("stable").unwrap(),
            T0,
            vec![release],
            None,
        )
        .unwrap();
        let feed = sign_envelope(
            PayloadKind::Feed,
            &feed.to_payload(),
            &signers,
            &Sha256Hasher,
            &Ed25519Verifier,
        )
        .unwrap();
        fs::write(copy.join("feed-stable.json"), feed).unwrap();

        let verify = w.verify(&copy, Some(T0));
        let inspect = w.run(&["inspect", s(&copy), "--at", &T0.to_string()], &[]);
        if tamper {
            let err = assert_fails(&verify, 1, "verify");
            assert!(err.contains("b.txt does not decode"), "{err:?}");
            assert_fails(&inspect, 1, "inspect");
            assert!(stdout(&inspect).is_empty(), "{}", stdout(&inspect));
        } else {
            assert_ok(&verify, "verify");
            // Both entries are decoded, though they share one frame.
            assert!(
                stdout(&verify).contains("manifest and pack ok (2 frame(s) decoded)"),
                "{}",
                stdout(&verify)
            );
            assert_ok(&inspect, "inspect");
        }
    }
}

/// Test 3: an expired feed fails `verify`; `feed refresh` at the later time fixes it.
#[test]
fn expiry_and_refresh() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let later = T0 + 400 * DAY;
    let out = w.verify(&r.dir, Some(later));
    let err = assert_fails(&out, 1, "verify 400 days later");
    assert!(err.contains("expired"), "{err:?}");
    // First-install floors: the same directory at the issue time is fine.
    assert_ok(
        &w.verify(&r.dir, Some(T0 + DAY)),
        "verify a day after issue",
    );

    assert_ok(
        &w.feed("refresh", &r.dir, None, &w.release[0], later, &[]),
        "feed refresh at +400 days",
    );
    assert_ok(&w.verify(&r.dir, Some(later)), "verify after the refresh");
    let feed = w.read_feed(&r.dir);
    assert_eq!(feed.issued(), later);
    assert_eq!(feed.expires(), Some(later + 90 * DAY));
}

/// Test 4: `seq` rises with every write, also within one second.
#[test]
fn seq_strictly_increases() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let first = w.read_feed(&r.dir).seq();
    assert_eq!(first, T0 * 1000);
    let mut seqs = vec![first];
    for _ in 0..2 {
        assert_ok(
            &w.feed("refresh", &r.dir, None, &w.release[0], T0, &[]),
            "feed refresh",
        );
        seqs.push(w.read_feed(&r.dir).seq());
    }
    assert!(seqs.windows(2).all(|p| p[0] < p[1]), "{seqs:?}");
    // add -> refresh -> refresh, then add again in the same second.
    let t = other_targets()[0];
    assert_ok(
        &w.pack(r.input.path(), &r.dir, "4.0.0", t, &w.release[0]),
        t,
    );
    assert_ok(
        &w.feed("add", &r.dir, Some("4.0.0"), &w.release[0], T0, &[]),
        "feed add",
    );
    let last = w.read_feed(&r.dir).seq();
    assert!(last > *seqs.last().unwrap());
}

/// Test 5: adding targets of a listed release keeps the earlier references byte-identical.
#[test]
fn adding_targets_keeps_references() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let reference = |feed: &VerifiedFeed, t: &str| {
        let release = &feed.releases()[0];
        let c = release
            .targets()
            .iter()
            .find(|(k, _)| k.as_str() == t)
            .map(|(_, c)| c.clone())
            .unwrap_or_else(|| panic!("no {t} in the feed"));
        (c.path().to_owned(), c.size(), c.sha256())
    };
    let mut listed = vec![WIN.to_owned()];
    let mut before = vec![reference(&w.read_feed(&r.dir), WIN)];
    for t in other_targets() {
        assert_ok(
            &w.pack(r.input.path(), &r.dir, "4.0.0", t, &w.release[0]),
            t,
        );
        // Packed but not listed yet.
        let out = w.verify(&r.dir, Some(T0));
        assert_ok(&out, "verify with an unreferenced manifest");
        assert!(
            stdout(&out).contains(&format!("4.0.0/{t}.manifest.json: unreferenced")),
            "{}",
            stdout(&out)
        );
        assert_ok(
            &w.feed("add", &r.dir, Some("4.0.0"), &w.release[0], T0, &[]),
            "feed add of a new target",
        );
        let feed = w.read_feed(&r.dir);
        assert_eq!(feed.releases().len(), 1);
        for (t0, b) in listed.iter().zip(&before) {
            assert_eq!(&reference(&feed, t0), b, "{t0} changed");
        }
        listed.push(t.to_owned());
        before.push(reference(&feed, t));
        assert_ok(&w.verify(&r.dir, Some(T0)), "verify");
    }
    assert_eq!(
        w.read_feed(&r.dir).releases()[0].targets().len(),
        listed.len()
    );
    assert!(!stdout(&w.verify(&r.dir, Some(T0))).contains(": unreferenced"));
}

/// A release dir whose manifest is signed by both release keys and whose feed by the first only;
/// then the first key is revoked.
fn revoked_world() -> (World, PathBuf) {
    let w = World::new(2);
    let (a, b) = (&w.release[0], &w.release[1]);
    let input = app_tree();
    let dir = w.release_dir("rel", &[a, b]);
    assert_ok(
        &w.pack_signed(input.path(), &dir, "4.0.0", WIN, &[a, b]),
        "pack",
    );
    assert_ok(&w.feed("add", &dir, Some("4.0.0"), a, T0, &[]), "feed add");
    assert_ok(&w.verify(&dir, Some(T0)), "verify before the revocation");

    // The guard stops this `keys set` (the feed is signed by `a` alone); the operator overrides it.
    let refused = w.keys_set_with(&dir, &[b], T0, &[]);
    assert_fails(&refused, 1, "keys set that would orphan the feed");
    let allowed = w.keys_set_with(&dir, &[b], T0, &["--allow-unverifiable-feeds"]);
    assert_ok(&allowed, "keys set --allow-unverifiable-feeds");
    assert!(
        stderr(&allowed).contains("feed-stable.json"),
        "{}",
        stderr(&allowed)
    );
    let out = w.verify(&dir, Some(T0));
    let err = assert_fails(&out, 1, "verify after the revocation");
    assert!(err.contains("feed-stable.json does not verify"), "{err:?}");
    // The revoked key can no longer sign anything new.
    let out = w.pack(input.path(), &dir, "4.0.1", WIN, a);
    let err = assert_fails(&out, 1, "pack with the revoked key");
    assert!(err.contains("not in keys.json"), "{err:?}");
    (w, dir)
}

/// Test 6: revoking the release key (`keys set` without it).
#[test]
fn revocation() {
    revoked_world();
}

/// State after move 1 of the revocation story: keys `[A]`, release 1.0.0 signed by A, a feed
/// signed by A at `T0`. Returns the world, the release dir, the app tree, A's feed bytes and seq.
fn after_move_1() -> (World, PathBuf, tempfile::TempDir, Vec<u8>, u64) {
    let w = World::new(3);
    let input = app_tree();
    let a = &w.release[0];
    let dir = w.release_dir("rel", &[a]);
    assert_ok(&w.pack(input.path(), &dir, "1.0.0", WIN, a), "pack 1.0.0");
    assert_ok(
        &w.feed("add", &dir, Some("1.0.0"), a, T0, &[]),
        "feed add 1.0.0",
    );
    let bytes = fs::read(dir.join("feed-stable.json")).unwrap();
    let seq = w.read_feed(&dir).seq();
    (w, dir, input, bytes, seq)
}

/// Test 6: revoking a release key in two moves (M3-R1-D1), every read verified.
#[test]
fn revocation_two_moves() {
    let (w, dir, input, feed1, seq1) = after_move_1();
    let (a, b) = (&w.release[0], &w.release[1]);

    // Move 2: keep A, add B; the previous feed verifies through A.
    w.keys_set(&dir, &[a, b]);
    assert_ok(&w.pack(input.path(), &dir, "1.1.0", WIN, b), "pack 1.1.0");
    assert_ok(
        &w.feed("add", &dir, Some("1.1.0"), b, T0, &[]),
        "feed add 1.1.0",
    );
    let seq2 = w.read_feed(&dir).seq();
    assert_ok(&w.feed("refresh", &dir, None, b, T0, &[]), "feed refresh");
    let seq3 = w.read_feed(&dir).seq();
    assert!(seq1 < seq2 && seq2 < seq3, "{seq1} {seq2} {seq3}");

    // Move 3: removing A now would orphan 1.0.0 (its manifest is signed by A alone).
    let keys_before = fs::read(dir.join("keys.json")).unwrap();
    let feed_before = fs::read(dir.join("feed-stable.json")).unwrap();
    let out = w.keys_set_with(&dir, &[b], T0, &[]);
    let err = assert_fails(&out, 1, "keys set [B] with 1.0.0 still listed");
    assert!(err.contains(&format!("1.0.0/{WIN}")), "{err:?}");
    assert!(err.contains("--drop"), "{err:?}");
    assert!(!err.contains("1.1.0/"), "{err:?}");
    assert_eq!(fs::read(dir.join("keys.json")).unwrap(), keys_before);
    assert_eq!(fs::read(dir.join("feed-stable.json")).unwrap(), feed_before);

    // A version the feed does not list cannot be dropped.
    let out = w.feed("refresh", &dir, None, b, T0, &["--drop", "9.9.9"]);
    assert_fails(&out, 1, "--drop of an unlisted version");
    assert_eq!(fs::read(dir.join("feed-stable.json")).unwrap(), feed_before);

    // Move 4: drop 1.0.0, then remove A.
    assert_ok(
        &w.feed("refresh", &dir, None, b, T0, &["--drop", "1.0.0"]),
        "feed refresh --drop 1.0.0",
    );
    let feed = w.read_feed(&dir);
    assert!(feed.seq() > seq3);
    assert_eq!(feed.releases().len(), 1);
    assert_eq!(feed.releases()[0].version_text(), "1.1.0");
    assert_ok(&w.keys_set_with(&dir, &[b], T0, &[]), "keys set [B]");
    assert_ok(&w.verify(&dir, Some(T0)), "verify after the revocation");

    // Move 5: A is revoked.
    let out = w.pack(input.path(), &dir, "1.2.0", WIN, a);
    assert_fails(&out, 1, "pack with the revoked key");
    let out = w.feed("refresh", &dir, None, a, T0, &[]);
    assert_fails(&out, 1, "feed refresh with the revoked key");
    let old = w.dir.path().join("rel-old");
    copy_dir(&dir, &old);
    fs::write(old.join("feed-stable.json"), &feed1).unwrap();
    let out = w.verify(&old, Some(T0));
    let err = assert_fails(&out, 1, "verify of A's old feed against the new keys.json");
    assert!(err.contains("feed-stable.json does not verify"), "{err:?}");
}

/// A feed with no release is valid (FORMAT section 7): `--drop` can empty it.
#[test]
fn dropping_every_release_leaves_an_empty_feed() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let before = w.read_feed(&r.dir).seq();
    assert_ok(
        &w.feed(
            "refresh",
            &r.dir,
            None,
            &w.release[0],
            T0,
            &["--drop", "4.0.0"],
        ),
        "feed refresh --drop",
    );
    let feed = w.read_feed(&r.dir);
    assert!(feed.releases().is_empty());
    assert!(feed.seq() > before);
    assert_ok(&w.verify(&r.dir, Some(T0)), "verify an empty feed");
}

/// Test 6, fallback: the operator revoked first. The feed is deleted and the channel restarted; the
/// new feed's seq stays above the old one only because the clock moved on.
#[test]
fn revocation_fallback_restarts_the_channel() {
    let (w, dir, input, _feed1, seq1) = after_move_1();
    let c = &w.release[2];

    // Without the flag the guard refuses and names the feed.
    let out = w.keys_set_with(&dir, &[c], T0, &[]);
    let err = assert_fails(&out, 1, "keys set [C] without the override");
    assert!(err.contains("feed-stable.json"), "{err:?}");

    let out = w.keys_set_with(&dir, &[c], T0, &["--allow-unverifiable-feeds"]);
    assert_ok(&out, "keys set [C] --allow-unverifiable-feeds");
    assert!(
        stderr(&out).contains("feed-stable.json"),
        "{}",
        stderr(&out)
    );
    assert_fails(&w.verify(&dir, Some(T0)), 1, "verify with an orphaned feed");

    for (verb, version) in [("refresh", None), ("add", Some("1.0.0"))] {
        let out = w.feed(verb, &dir, version, c, T0, &[]);
        let err = assert_fails(&out, 1, "feed write over an unverifiable feed");
        assert!(err.contains("delete it and run `feed add`"), "{err:?}");
        assert!(err.contains("feed-stable.json"), "{err:?}");
    }

    fs::remove_file(dir.join("feed-stable.json")).unwrap();
    let later = T0 + 60;
    let out = w.pack_signed_at(later, input.path(), &dir, "1.1.0", WIN, &[c]);
    assert_ok(&out, "pack 1.1.0 with C");
    assert_ok(
        &w.feed("add", &dir, Some("1.1.0"), c, later, &[]),
        "feed add 1.1.0 with C",
    );
    assert_ok(&w.verify(&dir, Some(later)), "verify after the restart");
    let seq = w.read_feed(&dir).seq();
    assert!(seq > seq1, "{seq} {seq1}");
}

/// `keys rotate-root` runs the same guard as `keys set`.
#[test]
fn rotate_root_runs_the_guard() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let new_root = w.new_key("root2");
    let (old_spec, new_spec) = (spec(&w.root), spec(&new_root));
    let args = [
        "keys",
        "rotate-root",
        "--release-dir",
        s(&r.dir),
        "--new-root-key",
        &new_root.public,
        "--new-threshold",
        "1",
        "--sign",
        &old_spec,
        "--sign-new",
        &new_spec,
    ];
    flip(&r.dir.join("feed-stable.json"));
    let keys_before = fs::read(r.dir.join("keys.json")).unwrap();
    let out = w.run_at(T0, &args);
    let err = assert_fails(&out, 1, "rotate-root over a damaged feed");
    assert!(err.contains("feed-stable.json"), "{err:?}");
    assert!(!r.dir.join("root-2.json").exists());
    assert_eq!(fs::read(r.dir.join("keys.json")).unwrap(), keys_before);

    let mut forced = args.to_vec();
    forced.push("--allow-unverifiable-feeds");
    let out = w.run_at(T0, &forced);
    assert_ok(&out, "rotate-root --allow-unverifiable-feeds");
    assert!(
        stderr(&out).contains("feed-stable.json"),
        "{}",
        stderr(&out)
    );
    assert!(r.dir.join("root-2.json").exists());
}

/// Writer refusals of `feed add`.
#[test]
fn feed_add_refusals() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let key = &w.release[0];

    // No manifest for the version.
    let out = w.feed("add", &r.dir, Some("9.9.9"), key, T0, &[]);
    assert_fails(&out, 1, "feed add of an unpacked version");

    // A version of equal precedence under other text.
    let twin = r.dir.join("4.0.0+b");
    copy_dir(&r.dir.join("4.0.0"), &twin);
    let out = w.feed("add", &r.dir, Some("4.0.0+b"), key, T0, &[]);
    let err = assert_fails(&out, 1, "equal precedence");
    assert!(err.contains("equal precedence"), "{err:?}");
    fs::remove_dir_all(&twin).unwrap();

    // A listed manifest is never replaced by different bytes.
    let t = other_targets()[0];
    assert_ok(&w.pack(r.input.path(), &r.dir, "4.0.0", t, key), t);
    fs::copy(
        r.dir.join(format!("4.0.0/{t}.manifest.json")),
        r.dir.join("4.0.0/windows-x86_64.manifest.json"),
    )
    .unwrap();
    let out = w.feed("add", &r.dir, Some("4.0.0"), key, T0, &[]);
    let err = assert_fails(&out, 1, "a replaced manifest");
    assert!(err.contains("never replaced"), "{err:?}");

    // refresh needs an existing feed; the signer must be in keys.json.
    let fresh = w.release_dir("fresh", &[key]);
    let out = w.feed("refresh", &fresh, None, key, T0, &[]);
    assert_fails(&out, 1, "refresh without a feed");
    let stranger = w.new_key("stranger");
    let out = w.feed("add", &r.dir, Some("4.0.0"), &stranger, T0, &[]);
    assert_fails(&out, 1, "feed add with a key outside keys.json");
}

/// A widened rollout keeps the release's seed.
#[test]
fn rollout_keeps_its_seed() {
    let w = World::new(1);
    let input = app_tree();
    let key = &w.release[0];
    let dir = w.release_dir("rel", &[key]);
    assert_ok(&w.pack(input.path(), &dir, "4.0.0", WIN, key), "pack");
    assert_ok(
        &w.feed("add", &dir, Some("4.0.0"), key, T0, &["--rollout", "1000"]),
        "feed add --rollout 1000",
    );
    let first = w.read_feed(&dir).releases()[0].rollout().unwrap();
    assert_eq!(first.basis_points, 1000);
    // Without a flag, a re-add keeps the rollout; with one, only the share changes.
    assert_ok(&w.feed("refresh", &dir, None, key, T0, &[]), "refresh");
    assert_eq!(w.read_feed(&dir).releases()[0].rollout().unwrap(), first);
    assert_ok(
        &w.feed("add", &dir, Some("4.0.0"), key, T0, &["--rollout", "10000"]),
        "feed add --rollout 10000",
    );
    let wide = w.read_feed(&dir).releases()[0].rollout().unwrap();
    assert_eq!((wide.basis_points, wide.seed), (10_000, first.seed));
    let out = w.verify(&dir, Some(T0));
    assert_ok(&out, "verify");
    let out = w.run(&["inspect", s(&dir), "--at", &T0.to_string()], &[]);
    assert!(
        stdout(&out).contains("rollout 10000 of 10000"),
        "{}",
        stdout(&out)
    );
}

// ---- the publisher state file (S1, M3-R2-D1) ------------------------------------------------------

/// The record of `APP` in the state file at `path`.
fn state_record(path: &Path) -> serde_json::Value {
    let v: serde_json::Value = serde_json::from_slice(&fs::read(path).unwrap()).unwrap();
    v["apps"][APP].clone()
}

impl World {
    fn state_path(&self) -> PathBuf {
        self.dir.path().join("lunepack-state.json")
    }

    /// A second publisher machine: a copy of the config and the state file in `name/`.
    fn second_machine(&self, name: &str) -> PathBuf {
        let d = self.dir.path().join(name);
        fs::create_dir(&d).unwrap();
        fs::copy(&self.config, d.join("lunepack.toml")).unwrap();
        fs::copy(self.state_path(), d.join("lunepack-state.json")).unwrap();
        d.join("lunepack.toml")
    }

    /// Like [`World::run_at`] with the config at `config`.
    fn run_with(&self, config: &Path, epoch: u64, args: &[&str]) -> Output {
        let mut full = vec!["--config", s(config)];
        full.extend_from_slice(args);
        self.cmd(&full, &[("SOURCE_DATE_EPOCH", &epoch.to_string())])
    }
}

/// The reviewer's replay: a halted rollout is undone by restoring the older feed, and the next
/// `feed refresh` (and `feed add`) refuses to re-sign it.
#[test]
fn replayed_feed_is_refused() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let feed = r.dir.join("feed-stable.json");
    let old = fs::read(&feed).unwrap();
    let old_seq = w.read_feed(&r.dir).seq();
    assert_ok(
        &w.feed(
            "add",
            &r.dir,
            Some("4.0.0"),
            &w.release[0],
            T0 + 60,
            &["--rollout", "0"],
        ),
        "halt the rollout",
    );
    let halted = w.read_feed(&r.dir).seq();
    assert_eq!(state_record(&w.state_path())["feeds"]["stable"], halted);
    fs::write(&feed, &old).unwrap();

    for (verb, version) in [("refresh", None), ("add", Some("4.0.0"))] {
        let out = w.feed(verb, &r.dir, version, &w.release[0], T0 + 120, &[]);
        let err = assert_fails(&out, 1, verb);
        assert!(err.contains("feed-stable.json"), "{err}");
        assert!(err.contains("may hold a replayed older copy"), "{err}");
        assert!(
            err.contains(&format!("seq {old_seq} ")) && err.contains(&format!("recorded {halted}")),
            "{err}"
        );
        assert_eq!(fs::read(&feed).unwrap(), old, "{verb}: nothing was written");
        assert_eq!(state_record(&w.state_path())["feeds"]["stable"], halted);
    }
}

/// A replayed older `keys.json` is refused by `keys set` and by `keys rotate-root`.
#[test]
fn replayed_key_set_is_refused() {
    let w = World::new(2);
    let (a, b) = (&w.release[0], &w.release[1]);
    let dir = w.release_dir("rel", &[a]);
    let keys = dir.join("keys.json");
    let old = fs::read(&keys).unwrap();
    let out = w.keys_set_with(&dir, &[a, b], T0 + 60, &["--threshold", "2"]);
    assert_ok(&out, "raise the threshold");
    let b_id = Sha256Hasher.sha256(&hex(&b.public)).to_hex();
    assert!(
        stdout(&out).contains(&format!(
            "change: version 1 -> 2: threshold 1 -> 2; added {b_id}"
        )),
        "{}",
        stdout(&out)
    );
    assert_eq!(state_record(&w.state_path())["keys_version"], 2);
    assert_eq!(state_record(&w.state_path())["keys_threshold"], 2);
    fs::write(&keys, &old).unwrap();

    let out = w.keys_set_with(&dir, &[a, b], T0 + 120, &["--threshold", "2"]);
    let err = assert_fails(&out, 1, "keys set on a replayed keys.json");
    assert!(
        err.contains("keys.json: version 1 in the release directory is older than the recorded 2"),
        "{err}"
    );
    assert!(err.contains("may hold a replayed older copy"), "{err}");
    assert_eq!(fs::read(&keys).unwrap(), old);

    let new_root = w.new_key("root2");
    let (old_side, new_side) = (spec(&w.root), spec(&new_root));
    let out = w.run_at(
        T0 + 120,
        &[
            "keys",
            "rotate-root",
            "--release-dir",
            s(&dir),
            "--new-root-key",
            &new_root.public,
            "--new-threshold",
            "1",
            "--sign",
            &old_side,
            "--sign-new",
            &new_side,
        ],
    );
    let err = assert_fails(&out, 1, "rotate-root on a replayed keys.json");
    assert!(err.contains("may hold a replayed older copy"), "{err}");
    assert!(!dir.join("root-2.json").exists());
    assert_eq!(fs::read(&keys).unwrap(), old);
}

/// No state file while the release directory holds documents: refused, unless
/// `--trust-release-dir`, which records the directory's values; the threshold is then not
/// inherited silently.
#[test]
fn missing_state_file() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let feed = r.dir.join("feed-stable.json");
    let before = fs::read(&feed).unwrap();
    fs::remove_file(w.state_path()).unwrap();

    let out = w.feed("refresh", &r.dir, None, &w.release[0], T0 + 60, &[]);
    let err = assert_fails(&out, 1, "refresh without a state file");
    assert!(err.contains("lunepack-state.json does not exist"), "{err}");
    assert!(err.contains("--trust-release-dir"), "{err}");
    assert_eq!(fs::read(&feed).unwrap(), before);
    assert!(!w.state_path().exists());

    let out = w.feed(
        "refresh",
        &r.dir,
        None,
        &w.release[0],
        T0 + 60,
        &["--trust-release-dir"],
    );
    assert_ok(&out, "refresh --trust-release-dir");
    assert!(
        stderr(&out).contains("--trust-release-dir"),
        "{}",
        stderr(&out)
    );
    let rec = state_record(&w.state_path());
    assert_eq!(rec["feeds"]["stable"], w.read_feed(&r.dir).seq());
    assert_eq!(rec["keys_version"], 1);
    assert_eq!(rec["keys_threshold"], 1);
    assert_eq!(rec["root_version"], 1);

    // keys set: refused without the flag, and with it the threshold must be given.
    fs::remove_file(w.state_path()).unwrap();
    let a = &w.release[0];
    let out = w.keys_set_with(&r.dir, &[a], T0 + 120, &[]);
    assert_fails(&out, 1, "keys set without a state file");
    let out = w.keys_set_with(&r.dir, &[a], T0 + 120, &["--trust-release-dir"]);
    let err = assert_fails(&out, 1, "keys set --trust-release-dir without --threshold");
    assert!(err.contains("pass --threshold"), "{err}");
    let out = w.keys_set_with(
        &r.dir,
        &[a],
        T0 + 120,
        &["--trust-release-dir", "--threshold", "1"],
    );
    assert_ok(&out, "keys set --trust-release-dir --threshold 1");
    assert_eq!(state_record(&w.state_path())["keys_version"], 2);
}

/// A previous document newer than the record (written by another trusted machine) is built on,
/// and the record follows it; a threshold that changed there must be given explicitly here.
#[test]
fn newer_previous_from_a_second_machine() {
    let w = World::new(2);
    let (a, b) = (&w.release[0], &w.release[1]);
    let input = app_tree();
    let dir = w.release_dir("rel", &[a]);
    assert_ok(&w.pack(input.path(), &dir, "4.0.0", WIN, a), "pack");
    assert_ok(&w.feed("add", &dir, Some("4.0.0"), a, T0, &[]), "feed add");
    let other = w.second_machine("machine2");
    let (sa, root) = (spec(a), spec(&w.root));
    let out = w.run_with(
        &other,
        T0 + 60,
        &[
            "feed",
            "refresh",
            "--release-dir",
            s(&dir),
            "--channel",
            "stable",
            "--sign",
            &sa,
        ],
    );
    assert_ok(&out, "refresh on the second machine");
    let theirs = w.read_feed(&dir).seq();
    assert_eq!(state_record(&w.state_path())["feeds"]["stable"], T0 * 1000);

    assert_ok(
        &w.feed("refresh", &dir, None, a, T0 + 120, &[]),
        "refresh on a newer feed",
    );
    let ours = w.read_feed(&dir).seq();
    assert!(ours > theirs);
    assert_eq!(state_record(&w.state_path())["feeds"]["stable"], ours);

    // The second machine raises the threshold; here it is not inherited silently.
    let out = w.run_with(
        &other,
        T0 + 180,
        &[
            "keys",
            "set",
            "--release-dir",
            s(&dir),
            "--release-key",
            &a.public,
            "--release-key",
            &b.public,
            "--threshold",
            "2",
            "--sign",
            &root,
            "--allow-unverifiable-feeds",
        ],
    );
    assert_ok(&out, "keys set on the second machine");
    let out = w.keys_set_with(&dir, &[a, b], T0 + 240, &["--allow-unverifiable-feeds"]);
    let err = assert_fails(
        &out,
        1,
        "keys set without --threshold after a change elsewhere",
    );
    assert!(
        err.contains("has threshold 2, but the state file records 1: pass --threshold"),
        "{err}"
    );
    let out = w.keys_set_with(
        &dir,
        &[a, b],
        T0 + 240,
        &["--threshold", "2", "--allow-unverifiable-feeds"],
    );
    assert_ok(&out, "keys set --threshold 2");
    assert!(
        stdout(&out).contains("change: version 2 -> 3: no change"),
        "{}",
        stdout(&out)
    );
    let rec = state_record(&w.state_path());
    assert_eq!(
        (rec["keys_version"].clone(), rec["keys_threshold"].clone()),
        (3.into(), 2.into())
    );
}

/// `--allow-older-previous` builds on the replayed feed, names it, and records the new seq.
#[test]
fn allow_older_previous_overrides() {
    let r = released("4.0.0", &[WIN]);
    let w = &r.w;
    let feed = r.dir.join("feed-stable.json");
    let old = fs::read(&feed).unwrap();
    assert_ok(
        &w.feed("refresh", &r.dir, None, &w.release[0], T0 + 60, &[]),
        "refresh",
    );
    fs::write(&feed, &old).unwrap();
    let out = w.feed(
        "refresh",
        &r.dir,
        None,
        &w.release[0],
        T0 + 120,
        &["--allow-older-previous"],
    );
    assert_ok(&out, "refresh --allow-older-previous");
    let err = stderr(&out);
    assert!(
        err.contains("feed-stable.json seq") && err.contains("--allow-older-previous"),
        "{err}"
    );
    let seq = w.read_feed(&r.dir).seq();
    assert_eq!(seq, (T0 + 120) * 1000);
    assert_eq!(state_record(&w.state_path())["feeds"]["stable"], seq);
}
